<script setup>
import { computed } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import Shell from '../Components/Shell.vue';
const props=defineProps({daily:Array,users:Array,from:String,to:String,providerError:String,eventCount:Number});
const filter=useForm({from:props.from,to:props.to});
const show = value => value==null ? 'Unavailable' : '$'+value;
const reconciled=computed(()=>!props.providerError && props.daily.every(x=>x.matches));
</script>
<template>
 <Head title="Usage and profit" /><Shell section="report"><header class="topbar"><span>WORKSPACE <span class="slash">/</span> USAGE & PROFIT</span><span class="provider-pill">Operator view</span></header><div class="page-heading"><div><span class="eyebrow">THE NUMBERS BEHIND THE FRAMES</span><h1>Every fraction, accounted for.</h1><p>Exact USD amounts, grouped by completion date in UTC.</p></div></div><div class="report-content"><form class="date-filter" @submit.prevent="filter.get('/report')"><label>From<input type="date" v-model="filter.from" required /></label><label>To<input type="date" v-model="filter.to" required /></label><button class="primary" :disabled="filter.processing">Update report</button></form><div :class="['reconcile-banner',reconciled?'matched':'mismatch']" role="status"><strong>{{ reconciled ? '✓ All provider costs and generation counts reconcile' : 'Reconciliation needs attention' }}</strong><p>{{ providerError || (reconciled ? 'Local records match Pixelforge usage for this environment’s API key.' : 'A difference is visible below. Pending callbacks or in-flight generations may need reconciliation.') }}</p><small>{{ eventCount }} unique webhook events recorded.</small></div><section class="panel report-panel"><h2>Daily totals</h2><p class="fine">No rounding in storage or calculations. Profit is user charges minus provider cost.</p><div class="table-scroll"><table><thead><tr><th>UTC date</th><th>Images</th><th>Users charged</th><th>Provider cost</th><th>Profit</th><th>Provider reported</th><th>Difference</th></tr></thead><tbody><tr v-for="row in daily" :key="row.date"><td>{{row.date}}</td><td>{{row.count}}</td><td>{{show(row.charged)}}</td><td>{{show(row.provider)}}</td><td>{{show(row.profit)}}</td><td>{{show(row.reported)}}</td><td :class="row.matches===false?'error-text':''">{{show(row.difference)}}</td></tr></tbody></table></div></section><section class="panel report-panel"><h2>By user</h2><p class="fine">User identifiers protect personal details in this shared demo report.</p><div class="table-scroll"><table><thead><tr><th>User</th><th>Images</th><th>Users charged</th><th>Provider cost</th><th>Profit</th></tr></thead><tbody><tr v-for="row in users" :key="row.name"><td>{{row.name}}</td><td>{{row.count}}</td><td>{{show(row.charged)}}</td><td>{{show(row.provider)}}</td><td>{{show(row.profit)}}</td></tr><tr v-if="!users.length"><td colspan="5">No completed, billable generations in this date range.</td></tr></tbody></table></div></section></div></Shell>
</template>
